/** Text handoffs are generated from the same immutable machine result. */
export function operatorBundle(report, pilot, release) {
  const cases = Object.values(report.cases)
  const blockers = cases.filter(c => c.status !== 'passed')
  const depRows = Object.values(report.dependencies).map(d => `| ${d.id} | ${d.status} | ${d.plan} | ${d.reasons.join('; ') || 'All named local suites passed'} |`).join('\n')
  const caseRows = cases.map(c => `| ${c.id} | ${c.description} | ${c.status} | ${(c.reasons ?? []).join('; ') || 'See hashed assertions'} |`).join('\n')
  const evidenceRows = (report.artifacts ?? []).map(a => `- [${a.path}](${a.path}) (${a.sha256}, ${a.bytes} bytes)`).join('\n')
  const nativeGaps = [
    { id: 'V05', source: 'packages/api/src/tasks/routine-intake.ts:admittedEvent; packages/core/src/workflow/scheduled-trigger.ts',
      accountableRole: 'senior engineer (readiness integration owner)', missing: `Current scheduled calendar preparation scenario or required foundation did not pass: ${(report.cases.V05?.reasons ?? []).join('; ')}. Native Calendar reads and scheduling exist; this does not establish an absent feature.`,
      smallestRepair: 'Inspect the captured native scheduled fixture and named foundation failures. Repair the demonstrated existing seam without creating a new scheduler.',
      acceptance: 'Owned PostgreSQL: admitted event + Project/Brief/tasks saves or delivers grounded prep; missing/private/cancelled/revoked source yields unknown/stop, no invented claims.', activationPrerequisite: 'F01/F02/F04/F07 acceptance plus real owner calendar/meeting/source/schedule bindings.' },
    { id: 'V06', source: 'packages/api/src/tasks/routine-intake.ts:admittedEvent; packages/api/src/tasks/routine-execution.ts; packages/api/src/workflow/channel-delivery.ts',
      accountableRole: 'senior engineer (F07 owner)', missing: 'Configured mailbox event admission and native bounded periodic source checkpoint/delivery deduplication are not demonstrated. Task-event replay alone is insufficient. Existing workflow web delivery is an explicit no-op, not a Chat suggestion delivery route.',
      smallestRepair: 'Implement the missing configured mailbox receipt/checkpoint and unchanged-input suppression through existing workflow/routine services under F07. No automatic replies or new independent work.',
      acceptance: 'Owned PostgreSQL with fake mailbox: source-backed Chat suggestions once, unchanged second run zero deliveries/Tasks, partial reads keep truthful checkpoint, plane/revocation tests and zero sends.', activationPrerequisite: 'F07 acceptance plus owner mailbox/assistant/scope/cadence/allowance/approval bindings on the correct plane.' },
  ].filter(g => report.cases[g.id]?.status !== 'passed')
  const dependencyGaps = Object.values(report.dependencies).filter(d => d.status !== 'passed').map(d => ({ id: d.id,
    source: d.plan, accountableRole: 'existing feature Goal owner and senior engineer', missing: d.reasons.join('; '),
    smallestRepair: 'Inspect the named suite results and repair only the demonstrated native seam in its owning Goal; preserve missing/skipped evidence as blocked.',
    acceptance: `Rerun every pinned suite for ${d.id} through this readiness CLI with a fresh directory; zero required skips and current source hashes.`,
    activationPrerequisite: 'Passing current native foundation and integration evidence, followed by owner activation review.' }))
  const gaps = [...dependencyGaps, ...nativeGaps, ...release.gaps]
  const remaining = `# Remaining work\n\nLocal readiness: **${report.verdicts.localReadiness}**. Live activation: **not checked**. No seven-day clock has started.\n\n`
    + gaps.map(g => `## ${g.id}\n\n- Current source/route: ${g.source}\n- Missing: ${g.missing}\n- Accountable role: ${g.accountableRole}\n- Smallest repair: ${g.smallestRepair}\n- Acceptance: ${g.acceptance}\n- Activation prerequisite: ${g.activationPrerequisite}\n`).join('\n')
    + '\n## Owed operations\n\nComplete named feature/release gaps; bind actual installation/member/assistant/account/Project/source identities and schedule/timezone/lead-time/allowance/approval/alert settings; verify remote CI/protection, exact-SHA artifacts, both maintainer/Brian route and target credentials/health/rollback; publish paired repositories only when authorized; production migrations/releases/deployments; installed/live account and semantic-quality acceptance; actual activation, seven days of use and founder review. Six-month commercial/OSS work remains the operating plan.\n'
  return {
    'readiness.md': `# Operations v1 readiness\n\nHarness: **${report.verdicts.codeHarness}**. Local: **${report.verdicts.localReadiness}**. Live: **not checked**.\n\nSource: OSS ${report.source.oss.sha}; platform ${report.source.platform.sha}. Content digest: ${report.source.digest}.\n\nThis report certifies only its source snapshot. Component DOM tests do not certify rendered browser layout or live semantic quality.\n\n| Dependency | Status | Existing handoff | Reason |\n|---|---|---|---|\n${depRows}\n\n| Case | Description | Status | Reason |\n|---|---|---|---|\n${caseRows}\n\n[Remaining work](remaining-work.md) · [Activation checklist](activation-checklist.md) · [Day-seven review](day-seven-review.md)\n\n## Evidence\n\n${evidenceRows}\n`,
    'remaining-work.md': remaining,
    'activation-checklist.md': `# Activation checklist\n\n**Blocked. readyToActivate: false.** Local verdict: ${report.verdicts.localReadiness}; live settings not checked.\n\nRequired non-passing cases: ${blockers.map(c => `${c.id} (${c.status})`).join(', ') || 'none; live review is still required'}.\n\n${depRows}\n\n- [ ] Close every named feature and release gap in [remaining work](remaining-work.md).\n- [ ] Owner chooses each recipe's installation plane: company platform, personal home-linux; customer sources stay in their own installation. No implicit sync or personal-account fallback.\n- [ ] Owner supplies actual member/assistant ids, mailbox/calendar, Project/source/private audience and Chat destination.\n- [ ] Owner sets exact cadence/timezone/meeting lead time, current Task/workspace allowances, approval/reviewer and alert settings. USD 1k is a flexible monthly reference.\n- [ ] Review materialized native definitions through current workflow/proposal controls and preflight tools/accounts/source authority. Drafts are not postable active definitions.\n- [ ] Verify installed accounts, semantic quality, remote CI/protection, exact candidate artifacts, maintainer/Brian release authority, credentials, application health and rollback under separate authorization.\n- [ ] Human activates only after all prerequisites close. This bundle creates/enables no live workflow or schedule.\n- [ ] For each lane use its bundled native start/pause/recover/disable/revoke controls. Disable future intake separately from existing Task Pause. Reconcile uncertain effects before retry; automatic recovery never renews allowance.\n- [ ] Founder records actual start date and conducts the seven-day adoption review.\n\nUnresolved fields per lane: ${pilot.recipes[0].unresolvedBindings.join(', ')}.\n`,
    'day-seven-review.md': '# Seven-day founder review (blank template)\n\nPilot has not started. Complete after actual readiness, owner binding and activation.\n\n- Actual activation date/time and plane: ______\n- Actual review date and founder reviewer: ______\n- Adoption outcome: did the intended four-to-five-person team centre work in Brian? Evidence and exceptions: ______\n- Every attempt, lane, result/failure, recovery and unresolved WIP: ______\n- Useful saved work and inspectable artifact/source references: ______\n- Remaining founder dependence for deployment and existing-client follow-up: ______\n- Actual cost, allowance stops and unnecessary manual burden: ______\n- Source/private/plane or authority incidents, if any: ______\n- Continue/change/pause decision and named owner: ______\n\nDo not infer offline work, fabricate usage/cost/productivity/MRR/star counts, or treat prepared drafts as completed operations. Six-month targets remain business targets.\n',
  }
}
